# GENERATED by tools/integration/build_nav_policy_pkg.py from ros2_ws/src/dh_core/dh_core/shadow/monitor.py -- do not edit here.
"""ShadowMonitor: normalized observations -> telemetry + Stage 4 verdicts. PURE and observational.

It owns no publisher, no follower and no command. The Milestone 1 SafetyGate is driven with an INERT
follower stand-in (nothing reads its speed_scale), so the gate's evaluation and clamp logic are
exercised exactly as they would be in flight, but the clamp is applied only to the MEASURED velocity
to report whether the current motion exceeds the limit.

Per evaluation (`evaluate(now)`, all times on the node clock):
  free_distance / valid_fraction  from the newest accepted depth frame (corridor along the direction
                                  of travel when moving, else straight ahead)
  approach_speed                  measured world velocity . corridor direction (>= 0)
  stop_distance                   stopping_distance(approach_speed)
  max_speed / verdict / reason    SafetyGate (SafetyEvaluator) judged at max(approach, probe_speed)
  loc_mode / loc_reason           health.LocalizationHealth (reused)
  rejects                         counters per reason for every observation that was not used
"""
from __future__ import annotations

import math
import time
from collections import Counter, deque
from dataclasses import dataclass, field
from typing import Deque, Dict, Optional

import numpy as np

from ..health import LocalizationHealth, LocHealthParams
from ..safety_filter import (LIMIT, SAFE, STOP, UNKNOWN, SafetyEvaluator, SafetyGate, SafetyParams, SensorInputs,
                             Verdict, stopping_distance)
from .clearance import ClearanceResult, CorridorParams, corridor_clearance
from .observation import (Intrinsics, OdomObs, StateObs, depth_from_msg, intrinsics_from_msg, odom_from_msg,
                          state_from_json, stamp_of)
from .streams import ClockParams, StreamMonitor, StreamParams
from .transforms import Extrinsic, heading_dir_to_world, level_rotation_enu_flu, world_dir_to_bearing


class _InertFollower:
    """Stands in for TrajectoryFollower so SafetyGate can run; nothing ever reads speed_scale."""
    speed_scale = 1.0
    traj = None


@dataclass
class ShadowConfig:
    safety: SafetyParams = field(default_factory=SafetyParams)
    corridor: CorridorParams = field(default_factory=CorridorParams)
    loc: LocHealthParams = field(default_factory=lambda: LocHealthParams(odom_timeout_s=0.6, require_vo_status=True))
    clock: ClockParams = field(default_factory=ClockParams)
    stream: StreamParams = field(default_factory=StreamParams)
    twist_in_child_frame: bool = True
    probe_speed: float = 0.5          # judge the verdict at max(approach speed, this)
    moving_speed: float = 0.10        # above this the corridor follows the velocity, else the heading
    max_pose_skew_s: float = 0.10     # depth frame needs an odometry sample within this of its stamp
    state_stale_s: float = 1.0
    jump_v_max: float = 1.5           # organizer twist cap, used for odometry-jump detection
    vo_tracking_state: int = 1


class ShadowMonitor:
    def __init__(self, cfg: ShadowConfig = ShadowConfig()):
        self.cfg = cfg
        mk = lambda n: StreamMonitor(n, cfg.stream, cfg.clock)
        self.streams: Dict[str, StreamMonitor] = {k: mk(k) for k in ("odom", "depth", "camera_info", "state", "vo")}
        self.loc = LocalizationHealth(cfg.loc)
        self.gate = SafetyGate(_InertFollower(), SafetyEvaluator(cfg.safety))
        self.rejects: Counter = Counter()
        self.odom: Optional[OdomObs] = None
        self.odom_hist: Deque[OdomObs] = deque(maxlen=90)
        self.state: Optional[StateObs] = None
        self.intr: Optional[Intrinsics] = None
        self.extr: Optional[Extrinsic] = None
        self.extr_reason = "no_tf"
        self.clear: Optional[ClearanceResult] = None
        self.clear_meta: Dict = {}
        self.depth_status = "DEPTH_MISSING"
        self.depth_obs = None
        self.last_report: Optional[Dict] = None

    # ------------------------------------------------------------------ inputs
    def set_extrinsic(self, extr: Optional[Extrinsic], reason: str = "") -> None:
        self.extr, self.extr_reason = extr, ("" if extr else (reason or "no_tf"))

    def on_odom(self, msg, rx: float) -> None:
        t0 = time.perf_counter()
        s = self.streams["odom"]
        use = s.on_message(stamp_of(msg), rx)
        o = odom_from_msg(msg, rx, self.cfg.twist_in_child_frame)
        if not use:
            self.rejects["odom_unstamped_dup_or_out_of_order"] += 1
        elif not o.valid:
            for r in o.reasons:
                self.rejects["odom_" + r] += 1
            self.odom = None                         # newest odometry is invalid: do not fall back to older
        else:
            self.odom = o
            self.odom_hist.append(o)
            self.loc.on_odom(rx, o.stamp, o.pos, pos_std=o.pos_std, v_max=self.cfg.jump_v_max, yaw=o.yaw)
        s.record_processing(time.perf_counter() - t0)

    def on_vo_status(self, vo_state: int, rx: float, stamp: Optional[float] = None) -> None:
        self.streams["vo"].on_message(stamp if stamp is not None else rx, rx)
        self.loc.on_vo_status(rx, int(vo_state))

    def on_state(self, data: str, rx: float) -> None:
        st, why = state_from_json(data, rx)
        self.streams["state"].on_message(st.stamp if st else None, rx)
        if st is None:
            self.rejects[why] += 1
            return
        self.state = st

    def on_camera_info(self, msg, rx: float) -> None:
        self.streams["camera_info"].on_message(stamp_of(msg), rx)
        intr, why = intrinsics_from_msg(msg)
        if intr is None:
            self.rejects[why] += 1
        else:
            self.intr = intr

    def _reject_depth(self, key: str) -> None:
        self.rejects[key] += 1
        self.depth_status = key.upper()
        self.clear = None                             # the newest frame is unusable: never keep an older verdict
        self.depth_obs = None

    def on_depth(self, msg, rx: float) -> None:
        t0 = time.perf_counter()
        try:
            self._on_depth(msg, rx)
        finally:
            self.streams["depth"].record_processing(time.perf_counter() - t0)

    def _on_depth(self, msg, rx: float) -> None:
        s = self.streams["depth"]
        stamp = stamp_of(msg)
        if not s.on_message(stamp, rx):
            self.rejects["depth_unstamped_dup_or_out_of_order"] += 1     # an older frame never replaces a newer one
            return
        if not s.clock.comparable:
            return self._reject_depth("depth_time_domain_" + s.clock.state.lower())
        if self.intr is None:
            return self._reject_depth("depth_no_camera_info")
        dep, why = depth_from_msg(msg, rx)
        if dep is None:
            return self._reject_depth(why)
        if dep.depth_m.shape != (self.intr.height, self.intr.width):
            return self._reject_depth("depth_camera_info_size_mismatch")
        if dep.frame_id != self.intr.frame_id:
            return self._reject_depth("depth_camera_info_frame_mismatch")
        if self.extr is None or self.extr.frame_id != dep.frame_id:
            return self._reject_depth("depth_" + (self.extr_reason if self.extr is None else "tf_frame_mismatch"))
        if not self.streams["odom"].clock.comparable:
            return self._reject_depth("depth_odom_time_domain_mismatch")
        pose = min(self.odom_hist, key=lambda o: abs(o.stamp - stamp), default=None)
        if pose is None or abs(pose.stamp - stamp) > self.cfg.max_pose_skew_s:
            return self._reject_depth("depth_no_pose_at_capture")
        R_lb = level_rotation_enu_flu(pose.quat)
        v = pose.vel_world
        moving = math.hypot(v[0], v[1]) > self.cfg.moving_speed
        bearing = world_dir_to_bearing(pose.yaw, v) if moving else 0.0
        res = corridor_clearance(dep.depth_m, self.intr.K, self.extr.R_body_cam, self.extr.t_body_cam, R_lb,
                                 bearing, self.cfg.corridor)
        self.clear = res
        self.depth_obs = dep
        self.clear_meta = {"stamp": stamp, "rx": rx, "dir_world": heading_dir_to_world(pose.yaw, bearing),
                           "pose_skew_s": abs(pose.stamp - stamp), "image_valid_fraction": dep.valid_fraction}
        self.depth_status = "OK"

    # ------------------------------------------------------------------ evaluation
    def evaluate(self, now: float) -> Dict:
        t0 = time.perf_counter()
        cfg = self.cfg
        loc_mode, loc_scale, loc_reason = self.loc.evaluate(now)
        o = self.odom
        approach = 0.0
        if o is not None and self.clear is not None:
            approach = max(0.0, float(np.dot(o.vel_world, self.clear_meta["dir_world"])))
        req = max(approach, cfg.probe_speed)
        # the frame shows the scene at capture time; the drone has closed in by approach * age since then
        free_now = None
        if self.clear is not None:
            age = max(0.0, now - self.clear_meta["stamp"])
            seen = min(self.clear.free_distance, cfg.safety.reliable_range)    # +inf = only the reliable range was seen
            free_now = max(0.0, seen - approach * age)
        pre = None
        if self.streams["odom"].clock.state == "MISMATCH":
            pre = Verdict(UNKNOWN, 0.0, "ODOM_TIME_DOMAIN_MISMATCH")    # before loc: its ages are meaningless
        elif self.loc.t_odom_rx is None:
            pre = Verdict(UNKNOWN, 0.0, "LOCALIZATION_UNKNOWN")
        elif loc_mode in ("HOVER", "ABORT"):
            pre = Verdict(STOP, 0.0, "LOCALIZATION_LOST")
        elif not self.streams["odom"].clock.comparable:
            pre = Verdict(UNKNOWN, 0.0, "ODOM_TIME_DOMAIN_UNDETERMINED")
        elif self.depth_status != "OK":
            pre = Verdict(UNKNOWN, 0.0, self.depth_status)
        if pre is not None:
            self.gate.last = pre
            self.gate.follower.speed_scale = 0.0
            verdict = pre
        else:
            inp = SensorInputs(now=now, free_distance=free_now, depth_stamp=self.clear_meta["stamp"],
                               depth_rx=self.clear_meta["rx"], depth_valid_fraction=self.clear.valid_fraction,
                               odom_stamp=o.stamp if o else None, odom_rx=o.rx if o else None,
                               pos_std=o.pos_std if o else None,
                               transform_valid=self.extr is not None and o is not None and o.valid,
                               loc_mode=loc_mode)
            verdict = self.gate.update(inp, req)
        v_meas = o.vel_world if o is not None else np.zeros(3)
        clamped, _ = self.gate.clamp(v_meas, 0.0)
        exceeds = bool(approach > verdict.max_speed + 1e-6)
        st = self.state if (self.state and now - self.state.rx <= cfg.state_stale_s) else None
        rep = {
            "t": now, "verdict": verdict.verdict, "max_speed": verdict.max_speed, "reason": verdict.reason,
            "free_distance_at_capture": None if self.clear is None else self.clear.free_distance,
            "free_distance": free_now,
            "valid_fraction": None if self.clear is None else self.clear.valid_fraction,
            "approach_speed": approach, "stop_distance": stopping_distance(approach, cfg.safety.latency_s, cfg.safety.brake_decel),
            "usable_distance": None if math.isnan(verdict.usable_distance) else verdict.usable_distance,
            "current_motion_exceeds_limit": exceeds,
            "measured_velocity_would_be_clamped": bool(np.linalg.norm(clamped) < np.linalg.norm(v_meas) - 1e-6),
            "loc_mode": loc_mode, "loc_reason": loc_reason, "depth_status": self.depth_status,
            "pose": None if o is None else {"pos": [float(c) for c in o.pos], "yaw": o.yaw,
                                            "vel_world": [float(c) for c in o.vel_world], "pos_std": o.pos_std},
            "state": None if st is None else {"armed": st.armed, "nav_state": st.nav_state_name,
                                              "offboard_active": st.offboard_active, "px4_link": st.px4_link,
                                              "clamped": st.clamped},
            "rejects": dict(self.rejects),
            "streams": {k: s.summary(now, include_processing=False) for k, s in self.streams.items()},
        }
        self.last_report = rep
        rep["_eval_proc_s"] = time.perf_counter() - t0          # wall-clock: excluded from deterministic output
        return rep

    def latest_observation(self, now: float):
        """The normalized bundle Stage 5 consumes (stage5_interfaces.NavObservation), or None without
        valid odometry. Depth is included only if the newest frame was accepted."""
        from ..stage5_interfaces import NavObservation
        if self.odom is None:
            return None
        rep = self.last_report if self.last_report and self.last_report["t"] == now else self.evaluate(now)
        return NavObservation(now, self.odom, self.depth_obs, self.intr, self.extr, rep["loc_mode"], deterministic(rep))

    def processing(self) -> Dict:
        return {k: {"p50_s": s.summary()["proc_p50_s"], "max_s": s.summary()["proc_max_s"]} for k, s in self.streams.items()}


def deterministic(rep: Dict) -> Dict:
    return {k: v for k, v in rep.items() if not k.startswith("_")}
